import { readFileSync } from 'node:fs'
import { getTransformedRoutes, isHandler } from '@vercel/routing-utils'
import { describe, expect, it } from 'vitest'

// vercel.json makes the content-hashed files under /_astro/ immutable (OPS-12),
// and the whole of the care in that rule is its scope. Two things must never
// fall inside it:
//
// - public/. og.png, apple-touch-icon.png and the favicons are regenerated by
//   scripts/images.ts under the SAME names. Immutable there is a stale social
//   card that nothing can flush.
// - the pages. Every page answers `no-store` (OPS-02), and that header is the
//   only thing forbidding a cache to keep the writings list (OPS-07).
//
// The rule is compiled here by @vercel/routing-utils, the library `vercel build`
// itself uses to turn vercel.json into .vercel/output/config.json, so the paths
// below are tested against the regex Vercel actually serves, not a copy of it.
//
// Why a rule in vercel.json at all, when the Astro adapter already writes the
// same header for ^/_astro/(.*)$ into config.json: the adapter's route sits
// after `{ handle: "filesystem" }`, and a static file is answered by that phase,
// so the route never applies to the files it was written for. Production served
// both hashed files `public, max-age=0, must-revalidate` until this rule. A
// vercel.json header is compiled ahead of the filesystem phase.

interface HeaderRule {
  source: string
  headers: { key: string; value: string }[]
}

function isHeaderRules(value: unknown): value is HeaderRule[] {
  return (
    Array.isArray(value) &&
    value.every(
      (rule: unknown) =>
        typeof rule === 'object' &&
        rule !== null &&
        'source' in rule &&
        typeof rule.source === 'string' &&
        'headers' in rule &&
        Array.isArray(rule.headers),
    )
  )
}

const parsed: unknown = JSON.parse(readFileSync(new URL('../vercel.json', import.meta.url), 'utf8'))
const rules: HeaderRule[] =
  typeof parsed === 'object' &&
  parsed !== null &&
  'headers' in parsed &&
  isHeaderRules(parsed.headers)
    ? parsed.headers
    : []

const { routes, error } = getTransformedRoutes({ headers: rules })

/** The Cache-Control a vercel.json rule would add to this path, if any. */
function cacheControlFor(path: string): string | undefined {
  let found: string | undefined
  for (const route of routes ?? []) {
    if (isHandler(route) || route.src === undefined || route.headers === undefined) continue
    if (!new RegExp(route.src).test(path)) continue
    for (const [key, value] of Object.entries(route.headers)) {
      if (key.toLowerCase() === 'cache-control') found = value
    }
  }
  return found
}

describe('the cache headers in vercel.json', () => {
  it('compile the way vercel build compiles them', () => {
    expect(error).toBeNull()
  })

  it('make the hashed build files immutable for a year', () => {
    for (const path of [
      '/_astro/Base.BCIddeEA.css',
      '/_astro/index.astro_astro_type_script_index_0_lang.DVnGbhMZ.js',
    ]) {
      expect(cacheControlFor(path)).toBe('public, max-age=31536000, immutable')
    }
  })

  it('leave the fixed-name files in public/ alone', () => {
    for (const path of ['/og.png', '/apple-touch-icon.png', '/favicon.ico', '/favicon.svg']) {
      expect(cacheControlFor(path)).toBeUndefined()
    }
  })

  it('never reach a page, which must keep its no-store', () => {
    for (const path of [
      '/',
      '/about',
      '/writings/some-slug',
      '/rss.xml',
      '/sitemap.xml',
      '/robots.txt',
      '/_astro',
      '/_astronaut',
    ]) {
      expect(cacheControlFor(path)).toBeUndefined()
    }
  })

  it('hold only the one rule, so a new one is a decision rather than a drift', () => {
    expect(rules.map((rule) => rule.source)).toEqual(['/_astro/(.*)'])
  })
})
